CREATE TABLE IF NOT EXISTS admins (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin' CHECK(role IN ('owner','admin')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT DEFAULT '', price INTEGER NOT NULL DEFAULT 0, image_url TEXT DEFAULT '', active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS videos (id TEXT PRIMARY KEY, title TEXT NOT NULL, embed_url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, source TEXT NOT NULL DEFAULT 'instagram', source_id TEXT, r2_key TEXT, image_url TEXT, caption TEXT DEFAULT '', occasion TEXT DEFAULT 'Other', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), published INTEGER NOT NULL DEFAULT 0, selected_by TEXT, width INTEGER, height INTEGER, bytes INTEGER NOT NULL DEFAULT 0, sharpness REAL DEFAULT 0, brightness REAL DEFAULT 0, exposure REAL DEFAULT 0, contrast REAL DEFAULT 0, clarity REAL DEFAULT 0, color REAL DEFAULT 0, composition REAL DEFAULT 0, similarity REAL DEFAULT 0, total_score REAL DEFAULT 0, phash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analytics_daily (day TEXT PRIMARY KEY, visitors INTEGER NOT NULL DEFAULT 0, pageviews INTEGER NOT NULL DEFAULT 0, mobile INTEGER NOT NULL DEFAULT 0, desktop INTEGER NOT NULL DEFAULT 0, tablet INTEGER NOT NULL DEFAULT 0, other INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, admin_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_photos_status ON photos(status);
CREATE INDEX IF NOT EXISTS idx_photos_published ON photos(published);
CREATE INDEX IF NOT EXISTS idx_photos_occasion ON photos(occasion);
